const MANIFEST = {
  name: "Familientagebuch",
  short_name: "Tagebuch",
  description: "Was war heute los bei der Familie?",
  start_url: "/",
  display: "standalone",
  background_color: "#FFF8F0",
  theme_color: "#E8871E",
  orientation: "portrait",
  icons: [
    { src: "/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any maskable" },
    { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any maskable" }
  ]
};

const SW = `
const CACHE = 'familientagebuch-v1';
self.addEventListener('install', e => self.skipWaiting());
self.addEventListener('activate', e => {
  e.waitUntil(
    caches.keys().then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k))))
  );
  self.clients.claim();
});
self.addEventListener('fetch', event => {
  const url = new URL(event.request.url);
  if (event.request.method !== 'GET' || url.pathname.startsWith('/api/')) return;
  event.respondWith(
    fetch(event.request).then(res => {
      const clone = res.clone();
      caches.open(CACHE).then(c => c.put(event.request, clone));
      return res;
    }).catch(() => caches.match(event.request))
  );
});
`;

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;

    try {
      if (path === "/manifest.json") {
        return json(MANIFEST, { "Content-Type": "application/manifest+json" });
      }
      if (path === "/sw.js") {
        return new Response(SW, { headers: { "Content-Type": "application/javascript" } });
      }
      if (path === "/icon-192.png") {
        return new Response(b64ToBytes(ICON_192_B64), { headers: { "Content-Type": "image/png" } });
      }
      if (path === "/icon-512.png") {
        return new Response(b64ToBytes(ICON_512_B64), { headers: { "Content-Type": "image/png" } });
      }

      if (path === "/api/login" && request.method === "POST") {
        const body = await request.json();
        const hash = await sha256Hex(body.password || "");
        if (hash === PASSWORD_HASH) {
          return json({ ok: true }, {
            "Set-Cookie": `${AUTH_COOKIE}=${PASSWORD_HASH}; Path=/; Max-Age=31536000; HttpOnly; Secure; SameSite=Lax`,
          });
        }
        return json({ ok: false }, {}, 401);
      }

      if (path === "/api/logout" && request.method === "POST") {
        return json({ ok: true }, {
          "Set-Cookie": `${AUTH_COOKIE}=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Lax`,
        });
      }

      // Ab hier: alles nur mit gültiger Anmeldung
      if (!isAuthenticated(request)) {
        if (path.startsWith("/api/")) {
          return json({ error: "Nicht angemeldet" }, {}, 401);
        }
        return new Response(LOGIN_HTML, { headers: { "Content-Type": "text/html; charset=UTF-8" } });
      }

      if (path === "/api/people" && request.method === "GET") {
        const { results } = await env.DB.prepare(
          "SELECT id, name, category, sort_order FROM people ORDER BY category, sort_order, id"
        ).all();
        return json(results);
      }

      if (path === "/api/people" && request.method === "POST") {
        const body = await request.json();
        const name = (body.name || "").trim();
        const category = (body.category || "").trim();
        if (!name || !category) return json({ error: "Name und Kategorie erforderlich" }, {}, 400);
        const row = await env.DB.prepare(
          "SELECT COALESCE(MAX(sort_order),0) as m FROM people WHERE category = ?"
        ).bind(category).first();
        const nextOrder = (row?.m || 0) + 1;
        const result = await env.DB.prepare(
          "INSERT INTO people (name, category, sort_order) VALUES (?, ?, ?)"
        ).bind(name, category, nextOrder).run();
        return json({ id: result.meta.last_row_id, name, category, sort_order: nextOrder });
      }

      if (path.match(/^\/api\/people\/\d+$/) && request.method === "DELETE") {
        const id = parseInt(path.split("/").pop());
        await env.DB.prepare("DELETE FROM entry_people WHERE person_id = ?").bind(id).run();
        await env.DB.prepare("DELETE FROM people WHERE id = ?").bind(id).run();
        return json({ ok: true });
      }

      if (path === "/api/entries" && request.method === "GET") {
        const { results: entries } = await env.DB.prepare(
          "SELECT id, date, note, importance FROM entries ORDER BY date, id"
        ).all();
        const { results: links } = await env.DB.prepare(
          "SELECT entry_id, person_id FROM entry_people"
        ).all();
        const byEntry = {};
        for (const l of links) {
          (byEntry[l.entry_id] = byEntry[l.entry_id] || []).push(l.person_id);
        }
        const out = entries.map(e => ({ id: e.id, date: e.date, note: e.note, importance: e.importance || 1, personIds: byEntry[e.id] || [] }));
        return json(out);
      }

      if (path === "/api/entries" && request.method === "POST") {
        const body = await request.json();
        const date = body.date;
        const note = (body.note || "").trim();
        const importance = [1,2,3].includes(body.importance) ? body.importance : 1;
        const personIds = Array.isArray(body.personIds) ? body.personIds : [];
        if (!date) return json({ error: "Datum erforderlich" }, {}, 400);
        const result = await env.DB.prepare(
          "INSERT INTO entries (date, note, importance) VALUES (?, ?, ?)"
        ).bind(date, note, importance).run();
        const entryId = result.meta.last_row_id;
        for (const pid of personIds) {
          await env.DB.prepare(
            "INSERT INTO entry_people (entry_id, person_id) VALUES (?, ?)"
          ).bind(entryId, pid).run();
        }
        return json({ ok: true, id: entryId, date, note, importance, personIds });
      }

      if (path.match(/^\/api\/entries\/\d+$/) && request.method === "PUT") {
        const entryId = parseInt(path.split("/").pop());
        const body = await request.json();
        const note = (body.note || "").trim();
        const importance = [1,2,3].includes(body.importance) ? body.importance : 1;
        const personIds = Array.isArray(body.personIds) ? body.personIds : [];
        await env.DB.prepare("UPDATE entries SET note = ?, importance = ? WHERE id = ?").bind(note, importance, entryId).run();
        await env.DB.prepare("DELETE FROM entry_people WHERE entry_id = ?").bind(entryId).run();
        for (const pid of personIds) {
          await env.DB.prepare(
            "INSERT INTO entry_people (entry_id, person_id) VALUES (?, ?)"
          ).bind(entryId, pid).run();
        }
        return json({ ok: true });
      }

      if (path.match(/^\/api\/entries\/\d+$/) && request.method === "DELETE") {
        const entryId = parseInt(path.split("/").pop());
        await env.DB.prepare("DELETE FROM entry_people WHERE entry_id = ?").bind(entryId).run();
        await env.DB.prepare("DELETE FROM entries WHERE id = ?").bind(entryId).run();
        return json({ ok: true });
      }

      if (path === "/api/backup" && request.method === "GET") {
        const { results: people } = await env.DB.prepare("SELECT id, name, category, sort_order FROM people").all();
        const { results: entries } = await env.DB.prepare("SELECT id, date, note, importance FROM entries").all();
        const { results: links } = await env.DB.prepare("SELECT entry_id, person_id FROM entry_people").all();
        return json({ version: 2, exportedAt: new Date().toISOString(), people, entries, links });
      }

      if (path === "/api/backup/restore" && request.method === "POST") {
        const body = await request.json();
        const { people = [], entries = [], links = [] } = body;
        await env.DB.batch([
          env.DB.prepare("DELETE FROM entry_people"),
          env.DB.prepare("DELETE FROM entries"),
          env.DB.prepare("DELETE FROM people"),
        ]);
        for (const p of people) {
          await env.DB.prepare(
            "INSERT INTO people (id, name, category, sort_order) VALUES (?, ?, ?, ?)"
          ).bind(p.id, p.name, p.category, p.sort_order || 0).run();
        }
        for (const e of entries) {
          await env.DB.prepare(
            "INSERT INTO entries (id, date, note, importance) VALUES (?, ?, ?, ?)"
          ).bind(e.id, e.date, e.note || "", e.importance || 1).run();
        }
        for (const l of links) {
          await env.DB.prepare(
            "INSERT INTO entry_people (entry_id, person_id) VALUES (?, ?)"
          ).bind(l.entry_id, l.person_id).run();
        }
        return json({ ok: true });
      }

      if (path === "/" || path === "/index.html") {
        return new Response(HTML, { headers: { "Content-Type": "text/html; charset=UTF-8" } });
      }

      return new Response("Not found", { status: 404 });
    } catch (err) {
      return json({ error: String(err) }, {}, 500);
    }
  },
};

function json(data, extraHeaders = {}, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "Content-Type": "application/json", ...extraHeaders },
  });
}

const HTML_B64 = "";
const HTML = new TextDecoder("utf-8").decode(b64ToBytes(HTML_B64));
